export const $=id=>document.getElementById(id);
export function number(id){const el=$(id),v=Number(el.value);if(!el.checkValidity()||!Number.isFinite(v))throw Error('Check '+(el.closest('label')?.textContent.trim()||id)+'.');return v;}
export function readSetup(){return {dx:number('dx'),dz:number('dz'),dt:$('autoDt').checked?.002:number('dtMs')/1000,autoDt:$('autoDt').checked,boundary:$('boundary').value,spongeWidth:number('spongeWidth'),spongeStrength:number('spongeStrength'),model:$('model').value,velocity:number('velocity'),lowerVelocity:number('lowerVelocity'),interfaceDepth:number('interfaceDepth'),sourceType:$('sourceType').value,sourceAmplitude:number('sourceAmplitude'),sourceWidth:$('sourceWidth').disabled?48:number('sourceWidth'),frequency:$('frequency').disabled?12:number('frequency'),sourceDelay:$('sourceDelay').disabled?0:number('sourceDelay'),sourceX:number('sourceX'),sourceZ:number('sourceZ')};}
export function sourceLabels(){const isRicker=$('sourceType').value==='ricker';$('sourceUnits').textContent=isRicker?'(a.u./m²)':'(a.u.)';$('frequency').disabled=!isRicker;$('sourceDelay').disabled=!isRicker;$('sourceWidth').disabled=isRicker;$('sourceHelp').textContent=isRicker?'Ricker: a time-dependent force in one grid cell. Peak time = activation + 1.5 / frequency. Amplitude is source density (a.u./m²).':'Gaussian: a zero-initial-velocity displacement with spatial standard deviation “Width”. Adding one is a single event, not continuous forcing.';}
